+///|
+async fn diagnostic_capture(reader : @process.ReadFromProcess, limit : Int32) -> (Bytes, Bool) {
+  let output = @buffer.Buffer(size_hint=limit)
+  let mut truncated = false
+  while reader.read_some(max_len=4096) is Some(chunk) {
+    let remaining = limit - output.length()
+    let count = if chunk.length() < remaining { chunk.length() } else { remaining }
+    if count > 0 {
+      output.write_bytes(chunk[:count])
+    }
+    if count < chunk.length() {
+      truncated = true
+    }
+  }
+  (output.to_bytes(), truncated)
+}
+
+///|
+async fn diagnostic_process_output(
+  program : String,
+  args : Array[String],
+  environment~ : Map[String, String],
+  cwd? : StringView,
+  stdin? : &@process.ProcessInput,
+  stdout_limit~ : Int32,
+  stderr_limit~ : Int32,
+) -> (Int32, Bytes, Bool, Bytes, Bool) {
+  let (out, stdout) = @process.read_from_process()
+  defer out.close()
+  let (err, stderr) = @process.read_from_process()
+  defer err.close()
+  @async.with_task_group(async fn(group) {
+    let child = @process.spawn(
+      group, program, args, extra_env=environment, inherit_env=false, cwd?, stdin?, stdout~, stderr~,
+    )
+    let output = group.spawn(async fn() { diagnostic_capture(out, stdout_limit) })
+    let errors = group.spawn(async fn() { diagnostic_capture(err, stderr_limit) })
+    let status = child.wait()
+    let (output, output_truncated) = output.wait()
