///|
async test "transport waits for a stopping supervisor and is supervised by its replacement" {
  let (directory, env) = fixture()
  defer cleanup_fixture(directory)
  let root = env.get("XDG_STATE_HOME").unwrap() + "/orca-env-devsy"
  @fs.mkdir(root, recursive=true)
  let lock = @fs.open(root + "/events.lock", mode=ReadWrite, create_mode=OpenOrCreate)
  defer lock.close()
  assert_true(lock.try_lock(Exclusive))
  defer {
    @fs.write_file(directory + "/owner-exit", "") catch { _ => () }
    if @fs.exists(directory + "/owned-proxy-pid") {
      let pid = @string.parse_int(@fs.read_file(directory + "/owned-proxy-pid").text())
      if pid > 1 { ignore(proxy_signal(-pid, 9)) }
    }
  }
  @async.with_timeout(15000, async fn() {
    @async.with_task_group(async fn(group) {
      let sink = @process.redirect_to_file("/dev/null", shared=true)
      defer sink.close()
      let old = @process.spawn(
        group, integration_binary(), ["--supervisor", root],
        extra_env=env, stdout=sink, stderr=sink, no_wait=true,
      )
      idle_wait_for(async fn() { @fs.exists(root + "/supervisor.json") })
      let old_pid = supervisor_pid(root)
      idle_wait_for(async fn() { !@fs.exists(root + "/supervisor.json") })
      assert_true(supervisor_alive(root))
      let command = quote(integration_binary()) +
        " --ssh-proxy '' /bin/sh -c " +
        quote("touch \"$HOME/transport-started\"; sleep 30") +
        " & echo $! > \"$HOME/owned-proxy-pid\"; while test ! -f \"$HOME/owner-exit\"; do sleep 0.05; done"
      let owner = @process.spawn(
        group, "/bin/sh", ["-c", command],
        extra_env=env, stdout=sink, stderr=sink, no_wait=true,
      )
      idle_wait_for(async fn() { @fs.exists(directory + "/owned-proxy-pid") })
      @async.sleep(100)
      assert_false(@fs.exists(directory + "/transport-started"))
      lock.unlock()
      assert_eq(old.wait(), 0)
      idle_wait_for(async fn() { @fs.exists(directory + "/transport-started") })
      let replacement = supervisor_pid(root)
      assert_false(replacement == old_pid)
      let proxy = @string.parse_int(@fs.read_file(directory + "/owned-proxy-pid").text())
      @fs.write_file(directory + "/owner-exit", "")
      assert_eq(owner.wait(), 0)
      idle_wait_for(() => process_start(proxy) == 0)
    })
  })
}
